from itertools import combinations
from typing import Dict, List, Set, Tuple

Frame = Dict[int, Set[int]]

def box(frame: Frame, a: Set[int]) -> Set[int]:
    return {w for w in frame if frame[w].issubset(a)}

def consistency(frame: Frame) -> Set[int]:
    return {w for w in frame if frame[w]}

def is_transitive(frame: Frame) -> bool:
    return all(frame.get(v, set()).issubset(s)
               for w, s in frame.items() for v in s)

def is_acyclic(frame: Frame) -> bool:
    colour = {w: 0 for w in frame}  # 0 white, 1 grey, 2 black
    def dfs(w: int) -> bool:
        colour[w] = 1
        for v in frame.get(w, set()):
            if colour.get(v, 0) == 1: return False
            if colour.get(v, 0) == 0 and not dfs(v): return False
        colour[w] = 2
        return True
    return all(colour[w] != 0 or dfs(w) for w in frame)

def enumerate_gl_frames(n: int) -> List[Frame]:
    pairs = [(a, b) for a in range(n) for b in range(n)]
    out: List[Frame] = []
    for k in range(len(pairs) + 1):
        for ch in combinations(pairs, k):
            f: Frame = {w: set() for w in range(n)}
            for a, b in ch: f[a].add(b)
            if is_transitive(f) and is_acyclic(f): out.append(f)
    return out

def main() -> None:
    for n in (1, 2, 3):
        frames = enumerate_gl_frames(n)
        ok = 0
        for f in frames:
            con = consistency(f)
            godel = box(f, con).issubset(box(f, set()))
            tangled = all(w not in box(f, con) for w in con)
            if godel and tangled: ok += 1
        print(f"n={n}: {len(frames)} GL frames, {ok} satisfy Godel II + tangling")

if __name__ == "__main__":
    main()

from typing import Dict, Set

Frame = Dict[int, Set[int]]

def box(frame: Frame, a: Set[int]) -> Set[int]:
    return {w for w in frame if frame[w].issubset(a)}

def nat_frame(bound: int) -> Frame:
    """Naturals 0..bound-1 with R a b <=> b < a."""
    return {a: set(range(a)) for a in range(bound)}

def iterated_box_bottom(frame: Frame, k: int) -> Set[int]:
    cur: Set[int] = set()
    for _ in range(k):
        cur = box(frame, cur)
    return cur

def main() -> None:
    frame = nat_frame(10)
    print("Rank identity box^k(bottom) = {0,...,k-1} on the naturals-under->:")
    for k in range(6):
        got = sorted(iterated_box_bottom(frame, k))
        print(f"  box^{k}(bottom) = {got}   expected {list(range(k))}")
        assert got == list(range(min(k, 10)))
    print("Consistency Con = {n >= 1}; box(Con) collapses to {0} = box(bottom).")
    con = {w for w in frame if frame[w]}
    print(f"  Con      = {sorted(con)}")
    print(f"  box(Con) = {sorted(box(frame, con))}")

if __name__ == "__main__":
    main()

from itertools import product
from typing import List

def anti_diagonal(f: List[List[bool]]) -> List[bool]:
    """d(a) = not f(a)(a): differs from row a at position a."""
    return [not f[a][a] for a in range(len(f))]

def in_range(f: List[List[bool]], p: List[bool]) -> bool:
    return any(row == p for row in f)

def main() -> None:
    n = 3
    total = escaped = 0
    # Enumerate every n x n boolean encoding; the anti-diagonal is never a row.
    for flat in product([False, True], repeat=n * n):
        f = [list(flat[i * n:(i + 1) * n]) for i in range(n)]
        d = anti_diagonal(f)
        total += 1
        if not in_range(f, d):
            escaped += 1
    print(f"n={n}: over {total} encodings, the anti-diagonal escaped "
          f"the range {escaped} times.")
    assert total == escaped
    print("No self-encoding onto Bool is surjective (Cantor / Tarski).")

if __name__ == "__main__":
    main()

